    import time

    LANGUAGE_WRAPPER = 'Let real variables x, y, c satisfy x >= 0, y >= 0, and x + y + c > \\sqrt({threshold}). For fixed parameters a = {a} and t = {t} (so k = t^2 - 1 = {k}), define\n\nE(x,y,c) = ((a + x^2)(4a + y^2)( {A}^2 + 2{k} c^2 + 4 c\\sqrt({k} + {k}c^2) )) / (( {A}\\sqrt{{k}}\\,c + 2{A}\\sqrt{1 + c^2} )(x + y)).\n\nDetermine the minimum value of E over all admissible x, y, c. Provide your final answer in simplest exact form.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose a = s^2 so the x,y part scales nicely and yields clean powers
s = rng.randint(1, 9)
a = s * s
# Choose t >= 2; k = t^2 - 1; c* = sqrt(k); S* = sqrt(1 + k) = t
t = rng.randint(2, 6)
k = t * t - 1
# Choose A so that the c-module f(c) has its unique stationary point at c = sqrt(k)
# From the derived derivative identity, the condition f'(sqrt(k)) = 0 forces:
# A^2 = 2 * t * (k + 2t)^2 / (t + 2)
A2 = 2.0 * t * (k + 2 * t) ** 2 / (t + 2)
A = A2 ** 0.5
# Pick a threshold (any positive integer works since feasibility is easy); keep it moderate
threshold = rng.randint(5, 50)
return {'a': a, 't': t, 'k': k, 'A': A, 'threshold': threshold}

    def verifier(assign):
try:
    a = assign['a']
    t = assign['t']
    k = assign['k']
    A = assign['A']
    threshold = assign['threshold']
except Exception:
    return (False, None)
# Basic validation
if not (isinstance(a, int) and a > 0):
    # a must be positive integer
    return (False, None)
if not (isinstance(t, int) and t >= 2):
    return (False, None)
if k != t * t - 1:
    return (False, None)
if not (isinstance(threshold, int) and threshold > 0):
    return (False, None)
# Recompute A from t and k to ensure consistency
import math
A2_expected = 2.0 * t * (k + 2 * t) ** 2 / (t + 2)
A_expected = math.sqrt(A2_expected)
if not (abs(A - A_expected) <= 1e-9 * max(1.0, A_expected)):
    # Inconsistent A
    return (False, None)
# The minimum splits into the x,y-module times the c-module at their respective minimizers.
# x,y-module: With substitution x = sqrt(a) * u, y = 2 sqrt(a) * v, the factor becomes
# 4 a^(3/2) * (1+u^2)(1+v^2)/(u+v), whose known minimum is K0 = 16 / 27^(1/4).
K0 = 16.0 / (27.0 ** 0.25)
xy_min = 4.0 * (a ** 1.5) * K0
# c-module: f(c) = (A^2 + 2k c^2 + 4 c sqrt(k + k c^2)) / (A sqrt(k) c + 2A sqrt(1 + c^2))
# With the chosen A, its unique stationary point is at c* = sqrt(k), which is the global minimum.
c_star = math.sqrt(k)
t_val = t  # since sqrt(1 + k) = t
# Evaluate f at c_star
num_star = (A ** 2) + 2.0 * (k ** 2) + 4.0 * k * t_val
den_star = A * (k + 2.0 * t_val)
if den_star <= 0:
    return (False, None)
f_min = num_star / den_star
answer = xy_min * f_min
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

